<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Http\Controllers\Concerns\HasSafePagination; use App\Http\Responses\ApiResponse; use App\Models\QualitySurvey; use App\Models\QualitySurveyQuestion; use App\Models\QualitySurveyResponse; use App\Models\QualitySurveySubmission; use Illuminate\Database\QueryException; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\Rule;
class QualitySurveyController extends Controller {
 use HasSafePagination;
 public function index(Request $request): JsonResponse { $items=QualitySurvey::withCount(['questions','responses'])->withCount(['responses as submissions_count'=>fn($q)=>$q->select(DB::raw('count(distinct submission_id)'))])->when($request->filled('academic_year'),fn($q)=>$q->where('academic_year',$request->string('academic_year')))->when($request->filled('status'),fn($q)=>$q->where('status',$request->string('status')))->orderByDesc('created_at')->paginate($this->perPage($request,25,100)); return ApiResponse::success($items->items(),null,['current_page'=>$items->currentPage(),'last_page'=>$items->lastPage(),'total'=>$items->total()]); }
 public function store(Request $request): JsonResponse { $data=$this->validatedSurvey($request); $data['public_id']=(string)Str::uuid(); $data['code']=filled($data['code']??null)?$data['code']:'SUR-'.str_pad((string)((QualitySurvey::max('id')??0)+1),4,'0',STR_PAD_LEFT); return ApiResponse::success(QualitySurvey::create($data),'Quality survey created.',[],201); }
 public function update(Request $request, QualitySurvey $qualitySurvey): JsonResponse { $qualitySurvey->update($this->validatedSurvey($request,$qualitySurvey)); return ApiResponse::success($qualitySurvey->fresh()->loadCount(['questions','responses']),'تم تحديث الاستبيان.'); }
 public function transition(Request $request, QualitySurvey $qualitySurvey): JsonResponse { $data=$request->validate(['status'=>['required',Rule::in(['draft','open','closed','archived'])]]); if($data['status']==='open' && $qualitySurvey->questions()->count()===0) return ApiResponse::error('لا يمكن نشر استبيان بلا أسئلة.',[],[],422); $qualitySurvey->update(['status'=>$data['status'],'is_active'=>!in_array($data['status'],['closed','archived'],true)]); return ApiResponse::success($qualitySurvey->fresh(),'تم تحديث حالة الاستبيان.'); }
 public function show(QualitySurvey $qualitySurvey): JsonResponse { return ApiResponse::success($qualitySurvey->load(['questions'=>fn($q)=>$q->orderBy('version')->orderBy('question_number')])); }
 public function responses(Request $request, QualitySurvey $qualitySurvey): JsonResponse { $responses=QualitySurveyResponse::with('question:id,question_text')->where('quality_survey_id',$qualitySurvey->id)->latest('responded_at')->paginate($this->perPage($request,50,100)); $summary=QualitySurveyResponse::query()->leftJoin('quality_survey_questions','quality_survey_questions.id','=','quality_survey_responses.quality_survey_question_id')->where('quality_survey_responses.quality_survey_id',$qualitySurvey->id)->groupBy('quality_survey_responses.quality_survey_question_id','quality_survey_questions.question_text')->get(['quality_survey_responses.quality_survey_question_id as question_id','quality_survey_questions.question_text',DB::raw('COUNT(*) as response_count'),DB::raw('AVG(quality_survey_responses.numeric_answer) as numeric_average')]); $submissionCount=QualitySurveyResponse::where('quality_survey_id',$qualitySurvey->id)->whereNotNull('submission_id')->distinct()->count('submission_id'); return ApiResponse::success(['responses'=>$responses->items(),'summary'=>$summary,'submission_count'=>$submissionCount],null,['current_page'=>$responses->currentPage(),'last_page'=>$responses->lastPage(),'total'=>$responses->total()]); }
 public function storeQuestion(Request $request, QualitySurvey $qualitySurvey): JsonResponse { $data=$request->validate(['version'=>['nullable','string','max:50'],'question_number'=>['nullable','integer','min:1'],'question_text'=>['required','string','max:3000'],'question_type'=>['required','string','max:100'],'options'=>['nullable','string','max:3000'],'is_required'=>['boolean'],'weight'=>['nullable','numeric','min:0'],'axis'=>['nullable','string','max:255'],'active_from'=>['nullable','date'],'active_until'=>['nullable','date']]); $data['version']??='1'; $data['question_number']??=((int)$qualitySurvey->questions()->where('version',$data['version'])->max('question_number'))+1; $data['quality_survey_id']=$qualitySurvey->id; return ApiResponse::success(QualitySurveyQuestion::create($data),'Survey question created.',[],201); }
 public function updateQuestion(Request $request, QualitySurvey $qualitySurvey, QualitySurveyQuestion $question): JsonResponse { abort_unless($question->quality_survey_id===$qualitySurvey->id,404); $data=$request->validate(['question_text'=>['required','string','max:3000'],'question_type'=>['required',Rule::in(['rating','single_choice','multiple_choice','short_text','long_text','number'])],'options'=>['nullable','string','max:3000'],'is_required'=>['boolean'],'axis'=>['nullable','string','max:255']]); $question->update($data); return ApiResponse::success($question->fresh(),'تم تحديث السؤال.'); }
 public function destroyQuestion(QualitySurvey $qualitySurvey, QualitySurveyQuestion $question): JsonResponse { abort_unless($question->quality_survey_id===$qualitySurvey->id,404); if(QualitySurveyResponse::where('quality_survey_question_id',$question->id)->exists()) return ApiResponse::error('لا يمكن حذف سؤال يحتوي على إجابات.',[],[],409); $question->delete(); return ApiResponse::success(null,'تم حذف السؤال.'); }
 public function responseMatrix(QualitySurvey $qualitySurvey): JsonResponse { $questions=$qualitySurvey->questions()->orderBy('question_number')->get(['id','question_number','question_text','question_type']); $answers=QualitySurveyResponse::where('quality_survey_id',$qualitySurvey->id)->whereNotNull('submission_id')->orderByDesc('responded_at')->get(); $submissions=$answers->groupBy('submission_id')->map(function($rows,$submissionId){$first=$rows->first();return ['submission_id'=>$submissionId,'responded_at'=>$first->responded_at,'respondent_identifier'=>$first->respondent_identifier,'answers'=>$rows->mapWithKeys(fn($row)=>[$row->quality_survey_question_id=>$row->numeric_answer??$row->text_answer])->all()];})->values(); return ApiResponse::success(['survey'=>$qualitySurvey->only(['id','code','title','status','is_anonymous']),'questions'=>$questions,'submissions'=>$submissions]); }
 public function storeResponse(Request $request, QualitySurvey $qualitySurvey): JsonResponse { $data=$request->validate(['quality_survey_question_id'=>['required','exists:quality_survey_questions,id'],'version'=>['required','string','max:50'],'respondent_identifier'=>['nullable','string','max:255'],'target_group'=>['nullable','string','max:255'],'course_id'=>['nullable','exists:courses,id'],'department_id'=>['nullable','exists:departments,id'],'training_site_id'=>['nullable','exists:training_sites,id'],'supervisor_person_id'=>['nullable','exists:people,id'],'numeric_answer'=>['nullable','numeric'],'text_answer'=>['nullable','string','max:5000']]); if(!QualitySurveyQuestion::where('id',$data['quality_survey_question_id'])->where('quality_survey_id',$qualitySurvey->id)->exists()) return ApiResponse::error('The question does not belong to this survey.',[],[],422); $data['quality_survey_id']=$qualitySurvey->id; $data['responded_at']=now(); return ApiResponse::success(QualitySurveyResponse::create($data),'Survey response recorded.',[],201); }
 public function publicShow(QualitySurvey $qualitySurvey): JsonResponse { if($qualitySurvey->status!=='open'||!$qualitySurvey->is_active) return ApiResponse::error('هذا الاستبيان غير متاح حاليًا.',[],[],404); if(($qualitySurvey->opens_at&&$qualitySurvey->opens_at->isFuture())||($qualitySurvey->closes_at&&$qualitySurvey->closes_at->endOfDay()->isPast())) return ApiResponse::error('هذا الاستبيان خارج فترة الاستجابة.',[],[],409); return ApiResponse::success($qualitySurvey->only(['public_id','title','target_group','purpose','is_anonymous','response_policy','is_mandatory','closes_at'])+['questions'=>$qualitySurvey->questions()->orderBy('question_number')->get(['id','question_number','question_text','question_type','options','is_required','axis'])]); }
 public function publicSubmit(Request $request, QualitySurvey $qualitySurvey): JsonResponse { if($qualitySurvey->status!=='open'||!$qualitySurvey->is_active) return ApiResponse::error('هذا الاستبيان غير متاح حاليًا.',[],[],409); if(($qualitySurvey->opens_at&&$qualitySurvey->opens_at->isFuture())||($qualitySurvey->closes_at&&$qualitySurvey->closes_at->endOfDay()->isPast())) return ApiResponse::error('هذا الاستبيان خارج فترة الاستجابة.',[],[],409); $data=$request->validate(['respondent_identifier'=>['nullable','string','max:255'],'respondent_token'=>['nullable','uuid'],'answers'=>['required','array','min:1'],'answers.*.question_id'=>['required','integer'],'answers.*.value'=>['nullable']]); if($qualitySurvey->response_policy==='one_per_identifier'&&blank($data['respondent_identifier']??null)) return ApiResponse::error('الرقم أو المعرّف مطلوب لضمان رد واحد لكل شخص.',[],[],422); if($qualitySurvey->response_policy==='one_per_device'&&blank($data['respondent_token']??null)) return ApiResponse::error('تعذر التحقق من الجهاز. حدّث الصفحة وحاول مجددًا.',[],[],422); $key=match($qualitySurvey->response_policy){'one_per_identifier'=>hash('sha256',mb_strtolower(trim($data['respondent_identifier']))),'one_per_device'=>hash('sha256',$data['respondent_token']),default=>null}; $questions=$qualitySurvey->questions()->get()->keyBy('id'); foreach($questions->where('is_required',true) as $question){$answer=collect($data['answers'])->firstWhere('question_id',$question->id);if(!$answer||blank($answer['value']??null))return ApiResponse::error('يرجى الإجابة عن جميع الأسئلة المطلوبة.',['question_'.$question->id=>['هذا السؤال مطلوب.']],[],422);} $submission=(string)Str::uuid(); try{DB::transaction(function()use($data,$questions,$qualitySurvey,$submission,$key){QualitySurveySubmission::create(['id'=>$submission,'quality_survey_id'=>$qualitySurvey->id,'respondent_key'=>$key,'respondent_identifier'=>$qualitySurvey->is_anonymous?null:($data['respondent_identifier']??null),'submitted_at'=>now()]);foreach($data['answers'] as $answer){$question=$questions->get((int)$answer['question_id']);if(!$question)continue;$numeric=in_array($question->question_type,['rating','number'],true)&&is_numeric($answer['value']??null);QualitySurveyResponse::create(['submission_id'=>$submission,'quality_survey_id'=>$qualitySurvey->id,'quality_survey_question_id'=>$question->id,'version'=>$question->version,'responded_at'=>now(),'respondent_identifier'=>$qualitySurvey->is_anonymous?null:($data['respondent_identifier']??null),'target_group'=>$qualitySurvey->target_group,'numeric_answer'=>$numeric?(float)$answer['value']:null,'text_answer'=>$numeric?null:($answer['value']??null)]);}});}catch(QueryException $e){if($key!==null)return ApiResponse::error('تم إرسال رد لهذا الاستبيان مسبقًا، ولا يسمح هذا النموذج بأكثر من رد.',[],[],409);throw $e;} return ApiResponse::success(['submission_id'=>$submission],'شكرًا، تم استلام إجابتك.',[],201); }
 private function validatedSurvey(Request $request, ?QualitySurvey $survey=null): array { return $request->validate(['code'=>['nullable','string','max:100',Rule::unique('quality_surveys','code')->ignore($survey?->id)],'title'=>['required','string','max:500'],'target_group'=>['required','string','max:255'],'academic_year'=>['nullable','string','max:100'],'purpose'=>['nullable','string','max:3000'],'frequency'=>['nullable','string','max:100'],'opens_at'=>['nullable','date'],'closes_at'=>['nullable','date','after_or_equal:opens_at'],'expected_responses'=>['nullable','integer','min:1'],'responsible'=>['nullable','string','max:255'],'form_url'=>['nullable','url','max:2000'],'is_mandatory'=>['boolean'],'is_anonymous'=>['boolean'],'response_policy'=>['sometimes',Rule::in(['multiple','one_per_device','one_per_identifier'])],'notes'=>['nullable','string','max:3000'],'status'=>['sometimes',Rule::in(['draft','open','closed','archived'])]]); }
}
